62	import java.io.IOException;
63	import java.io.UncheckedIOException;
64	import java.nio.charset.StandardCharsets;
65	import java.nio.file.Files;
66	import java.nio.file.Path;
67	import java.nio.file.StandardOpenOption;
68	import org.springframework.beans.factory.annotation.Value;
69	import org.springframework.stereotype.Service;
70	import org.springframework.transaction.support.TransactionSynchronization;
71	import org.springframework.transaction.support.TransactionSynchronizationManager;
72	
73	/**
74	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
75	 * so tests can assert side-effects by reading that file — the second test-assertion channel
76	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
77	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
78	 *
79	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
80	 * SYNC) so a test reads the record immediately.
81	 */
82	@Service
83	public class Audit {
84	
85	    private final Path file;
86	
87	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
88	        this.file = Path.of(path);
89	    }
90	
91	    /** Append one audit record. Tests assert the exact line(s) in the file. */
92	    public synchronized void record(String entry) {
93	        try {
94	            Path parent = file.toAbsolutePath().getParent();
95	            if (parent != null) {
96	                Files.createDirectories(parent);
97	            }
98	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
99	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
100	        } catch (IOException e) {
101	            throw new UncheckedIOException(e);
102	        }
103	    }
104	
105	    /**
106	     * Append one audit record once the current transaction commits, so a change that is refused or
107	     * rolled back writes nothing. Outside a transaction the record is appended at once.
108	     */
109	    public void recordOnCommit(String entry) {
110	        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
111	            record(entry);
112	            return;
113	        }
114	        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
115	            @Override
116	            public void afterCommit() {
117	                record(entry);
118	            }
119	        });
120	    }
121	
122	    /** Truncate the audit file. */
123	    public synchronized void clear() {
124	        try {
125	            Files.deleteIfExists(file);
126	        } catch (IOException e) {
127	            throw new UncheckedIOException(e);
128	        }
129	    }
