458	    /** The sheet's claims, newest first. */
459	    @Transactional(readOnly = true)
460	    public List<Claim> list(String sheetId) {
461	        sheets.today(sheetId); // the sheet must exist
462	        return claims.findBySheetIdOrderByIdDesc(sheetId);
463	    }
