465	    /** Add a claim for a person; a claim without a date is dated the sheet's today. One dated in a closed period
466	     * is refused, and so is a correction that does not name a settled claim of the same person. */
467	    @Transactional
468	    public Claim add(String user, String sheetId, Long personId, BigDecimal amount, LocalDate date, String note,
469	            Integer corrects) {
470	        LocalDate today = sheets.today(sheetId);
471	        Person person = requirePerson(sheetId, personId);
472	        requireNotRetired(person, date != null ? date : today);
473	        requireOpenPeriod(sheetId, date != null ? date : today);
474	        Integer corrected = correctedBy(sheetId, personId, amount, corrects);
475	        Snapshot before = rollup.snapshot(sheetId);
476	        Claim fresh = new Claim(sheetId, personId, amount, date != null ? date : today, noteOf(note));
477	        fresh.setCorrects(corrected);
478	        Claim claim = claims.saveAndFlush(fresh);
479	        audit.recordOnCommit(entry("CLAIM_ADDED", user, person, claim));
480	        rollup.recordChanges(user, sheetId, before);
481	        return claim;
482	    }
