487	    @Transactional
488	    public Claim update(String user, String sheetId, Long id, BigDecimal amount, LocalDate date, String note,
489	            Integer corrects) {
490	        LocalDate today = sheets.today(sheetId);
491	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
492	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
493	        if (claim.getStatus() != ClaimStatus.DRAFT) {
494	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft claim can be edited.");
495	        }
496	        requireOpenPeriod(sheetId, claim.getDate());
497	        requireOpenPeriod(sheetId, date != null ? date : today);
498	        requireNotRetired(requirePerson(sheetId, claim.getPersonId()), date != null ? date : today);
499	        Integer corrected = correctedBy(sheetId, claim.getPersonId(), amount, corrects);
500	        Snapshot before = rollup.snapshot(sheetId);
501	        claim.setAmount(amount);
502	        claim.setCorrects(corrected);
503	        claim.setDate(date != null ? date : today);
504	        claim.setNote(noteOf(note));
505	        claims.flush();
506	        audit.recordOnCommit(entry("CLAIM_EDITED", user, requirePerson(sheetId, claim.getPersonId()), claim));
507	        rollup.recordChanges(user, sheetId, before);
508	        return claim;
