511	    /** Move a claim to another status; a change its status does not allow, or of a claim dated in a closed
512	     * period, is refused; so is a settle by a clerk of a claim whose due is above the clerk limit. */
513	    @Transactional
514	    public Claim changeStatus(String user, String sheetId, Long id, ClaimStatus next) {
515	        sheets.today(sheetId); // the sheet must exist
516	        // Taking the number first locks the sheet, so claims are opened one at a time; a refused
517	        // open rolls back and gives the number back.
518	        Integer number = next == ClaimStatus.OPEN ? sheets.nextClaimNumber(sheetId) : null;
519	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
520	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
521	        requireOpenPeriod(sheetId, claim.getDate());
522	        if (!claim.getStatus().canBecome(next)) {
523	            throw new ResponseStatusException(HttpStatus.CONFLICT,
524	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
525	        }
526	        // Four eyes: whoever opened a claim cannot also settle it.
527	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
528	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it.");
529	        }
530	        Person person = requirePerson(sheetId, claim.getPersonId());
