535	        Snapshot before = rollup.snapshot(sheetId);
536	        BigDecimal due = rollup.dueOf(claim, person);
537	        claim.setStatus(next);
538	        if (next == ClaimStatus.OPEN) {
539	            claim.setNumber(number);
540	            claim.setOpenedBy(user);
541	        }
542	        // A voided claim's line carries the number it had.
543	        String entry = entry(EVENTS.get(next), user, person, claim);
544	        if (next == ClaimStatus.SETTLED) {
545	            // Settling fixes the due at the figure the claim has: the one its last statement bound it to, else
546	            // the rate its grade has on its date; with no figure it stays live. The late charge it has (taken
547	            // while it is still OPEN) is frozen in.
548	            claim.setSettledDue(due);
549	            entry += " due=" + (claim.getSettledDue() != null ? claim.getSettledDue().toPlainString() : "n/a");
550	        }
551	        claims.flush();
552	        audit.recordOnCommit(entry);
553	        rollup.recordChanges(user, sheetId, before);
554	        return claim;
