557	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
558	            ClaimStatus.OPEN, "CLAIM_OPENED",
559	            ClaimStatus.SETTLED, "CLAIM_SETTLED",
560	            ClaimStatus.VOID, "CLAIM_VOIDED");
