569	     * SETTLED claim of the same person, or the claim is refused. */
570	    private Integer correctedBy(String sheetId, Long personId, BigDecimal amount, Integer corrects) {
571	        if (amount.signum() >= 0) {
572	            return null;
573	        }
574	        boolean settled = corrects != null && claims.findBySheetIdAndPersonId(sheetId, personId).stream()
575	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
576	        if (!settled) {
