853	     * overlaps another of the sheet's periods is refused. */
854	    @Transactional
855	    public Period add(String user, String sheetId, String name, LocalDate from, LocalDate to) {
856	        // Locking the sheet adds its periods one at a time, so two at once cannot overlap.
857	        sheets.lock(sheetId);
858	        String trimmed = name.trim();
859	        if (to.isBefore(from)) {
860	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period cannot end before it starts.");
861	        }
862	        if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, trimmed)) {
863	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
864	        }
865	        if (periods.findBySheetIdOrderByFromAsc(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
866	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another.");
867	        }
868	        Period period;
869	        try {
870	            period = periods.saveAndFlush(new Period(sheetId, trimmed, from, to));
871	        } catch (DataIntegrityViolationException e) {
872	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
873	        }
874	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + period.getName()
875	                + " from=" + period.getFrom() + " to=" + period.getTo());
876	        return period;
877	    }
