882	        // Locking the sheet keeps claims from changing while the total is taken.
883	        sheets.lock(sheetId);
884	        Period period = periods.findByIdAndSheetId(id, sheetId)
885	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
886	        if (period.isClosed()) {
