888	        }
889	        BigDecimal total = rollup.dueTotal(sheetId, period.getFrom(), period.getTo());
890	        period.close(total);
891	        periods.flush();
892	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + period.getName()
893	                + " total=" + total.toPlainString());
894	        return period;
