1859	        BigDecimal floor = floorOf(sheetId);
1860	        Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
1861	        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
1862	        for (Claim claim : all) {
