217	export class People {
218	  private readonly session = inject(Session);
219	  private readonly api = inject(PeopleApi);
220	  private readonly claimsApi = inject(ClaimsApi);
221	  private readonly ratesApi = inject(RatesApi);
222	  private readonly periodsApi = inject(PeriodsApi);
223	  private readonly floor = inject(SheetFloor);
224	  private readonly terms = inject(SheetTerms);
225	  private readonly latePct = inject(SheetLatePct);
226	  private readonly policyDate = inject(SheetPolicyDate);
227	  /** What a late charge goes by: the sheet's today, terms and late percent; and the policy date rounding goes
228	   * by. */
229	  private readonly late = computed<Lateness>(() => ({
230	    today: this.session.today(),
231	    terms: this.terms.value(),
232	    latePct: this.latePct.value(),
233	    policyDate: this.policyDate.value() ?? this.session.today(),
234	  }));
235	
236	  protected readonly grades: Grade[] = ['A', 'B', 'C'];
237	  protected readonly people = signal<Person[]>([]);
238	  /** Whether retired people are listed; off when the screen opens, and kept as it is by loading a sheet. */
239	  protected readonly showRetired = signal(false);
240	  /** The people listed: everyone, or only those not retired unless retired people are shown. Totals count
241	   * everyone either way. */
242	  protected readonly shownPeople = computed(() =>
243	    this.showRetired() ? this.people() : this.people().filter((p) => !p.retiredFrom),
244	  );
245	  /** The sheet's claims, newest first. */
246	  protected readonly claims = signal<Claim[]>([]);
247	  private readonly claimsByPerson = computed(() => {
248	    const by = new Map<number, Claim[]>();
249	    for (const c of this.claims()) by.set(c.personId, [...(by.get(c.personId) ?? []), c]);
250	    return by;
251	  });
252	  /** The ids of the people on hold, whose OPEN claims count in no total. */
253	  private readonly heldIds = computed(() => new Set(this.people().filter((p) => p.held).map((p) => p.id)));
254	  protected readonly claimedTotal = computed(() =>
255	    sumAmounts(this.claims().filter((c) => this.countsLive(c)).map((c) => c.amount)),
256	  );
257	  /** The sheet's rates. */
258	  protected readonly rates = signal<Rate[]>([]);
259	  /** The rate each grade with one has in force on the sheet's today. */
260	  protected readonly rateByGrade = computed(() => {
261	    const today = this.session.today() ?? '';
262	    const by = new Map<Grade, string>();
263	    for (const g of this.grades) {
264	      const rate = rateOn(this.rates(), g, today);
265	      if (rate !== undefined) by.set(g, rate);
266	    }
267	    return by;
268	  });
269	
270	  /** The sheet's periods by from-date. */
271	  protected readonly periods = signal<Period[]>([]);
272	  /** Each period's due-total, by id: the sum of the dues of the claims that count dated in it (n/a ones
273	   * skipped), 0.00 with none; a closed period's is the one fixed when it closed. */
274	  protected readonly periodDueTotals = computed(() => {
275	    const byId = new Map(this.people().map((p) => [p.id, p]));
276	    const dues = new Map<number, string[]>();
277	    for (const c of this.claims().filter((c) => this.countsLive(c))) {
278	      const period = periodOf(this.periods(), c.date);
279	      const person = byId.get(c.personId);
280	      if (!period || !person) continue;
281	      const due = this.claimDue(c, person);
282	      if (due !== NO_RATE) dues.set(period.id, [...(dues.get(period.id) ?? []), due]);
283	    }
284	    return new Map(this.periods().map((p) => [p.id, p.closedTotal ?? sumAmounts(dues.get(p.id) ?? [])]));
285	  });
286	
287	  protected readonly dueTotal = computed(() =>
288	    sumAmounts(this.people().map((p) => this.personDueTotal(p)).filter((d) => d !== NO_RATE)),
289	  );
290	  /** Per grade, the people not retired who have it on the sheet's today and their due-totals added up (n/a
291	   * ones skipped). */
292	  protected readonly gradeSummary = computed<GradeSummary[]>(() =>
293	    this.grades.map((grade) => {
294	      const on = this.people().filter((p) => !p.retiredFrom && this.gradeToday(p) === grade);
295	      const dueTotal = sumAmounts(on.map((p) => this.personDueTotal(p)).filter((d) => d !== NO_RATE));
296	      return { grade, count: on.length, dueTotal };
297	    }),
298	  );
299	  /** How many of the sheet's claims have each status. */
300	  protected readonly statusCounts = computed(() => {
301	    const by = new Map<string, number>();
302	    for (const c of this.claims()) by.set(c.status, (by.get(c.status) ?? 0) + 1);
303	    return by;
304	  });
305	  /** How many of the sheet's claims that count are overdue, and the sum of their dues (n/a ones skipped). */
306	  protected readonly overdueCount = computed(() =>
307	    this.people().reduce((n, p) => n + this.overdueOf(p).length, 0),
308	  );
309	  protected readonly overdueTotal = computed(() => sumAmounts(this.people().map((p) => this.overdueTotalOf(p))));
310	  protected readonly editingId = signal<number | null>(null);
311	  /** The version of the person the editor loaded. */
312	  private editingVersion: number | null = null;
313	  /** Whether a submit is waiting on the server; another submit is ignored until it answers. */
314	  private submitting = false;
315	  protected readonly formError = signal<string | null>(null);
316	  /** The error of the last action taken on a person's row, shown on that row. */
317	  protected readonly personError = signal<{ id: number; message: string } | null>(null);
318	  /** The error of the last patron added on a person's row, shown on that row. */
319	  protected readonly patronError = signal<{ id: number; message: string } | null>(null);
320	  protected readonly form = new FormGroup({
321	    name: new FormControl('', { nonNullable: true }),
322	    grade: new FormControl<Grade>('A', { nonNullable: true }),
323	    /** The date a saved grade is in force from; the sheet's today unless another date is picked. */
324	    gradeFrom: new FormControl('', { nonNullable: true }),
325	  });
326	
327	  /** Whether a quick-add is waiting on the server; another is ignored until it answers. */
328	  private quickAdding = false;
329	  protected readonly quickError = signal<string | null>(null);
330	  protected readonly quickForm = new FormGroup({
331	    name: new FormControl('', { nonNullable: true }),
332	    amount: new FormControl('', { nonNullable: true }),
333	  });
334	
335	  constructor() {
336	    this.form.valueChanges.subscribe(() => this.formError.set(null));
337	    this.quickForm.valueChanges.subscribe(() => this.quickError.set(null));
338	    effect(() => {
339	      const today = this.session.today() ?? '';
340	      untracked(() => {
341	        if (!this.form.controls.gradeFrom.dirty) this.form.controls.gradeFrom.setValue(today, { emitEvent: false });
342	      });
343	    });
344	    // Re-read the sheet's people and their claims from the store each time a sheet is loaded.
345	    const loaded = this.session.registerLoader(inject(DestroyRef));
346	    toObservable(this.session.sheetId)
347	      .pipe(
348	        switchMap((id) =>
349	          id
350	            ? forkJoin({
351	                id: of(id),
352	                people: this.api.list(id),
353	                claims: this.claimsApi.list(id),
354	                rates: this.ratesApi.list(id),
355	                periods: this.periodsApi.list(id),
356	              })
357	            : of({ id, people: [] as Person[], claims: [] as Claim[], rates: [] as Rate[], periods: [] as Period[] }),
358	        ),
359	      )
360	      .subscribe(({ id, people, claims, rates, periods }) => {
361	        this.people.set(people);
362	        this.periods.set(periods);
363	        this.claims.set(claims);
364	        this.rates.set(rates);
365	        this.reset();
366	        loaded(id);
367	      });
368	  }
369	
370	  protected claimsOf(personId: number): Claim[] {
371	    return this.claimsByPerson().get(personId) ?? [];
372	  }
373	
374	  protected claimed(personId: number): string {
375	    return sumAmounts(this.claimsOf(personId).filter((c) => this.countsLive(c)).map((c) => c.amount));
376	  }
377	
378	  /** The grade the person has in force on the sheet's today. */
379	  protected gradeToday(person: Person): Grade {
380	    const today = this.session.today();
381	    return (today !== null ? gradeOn(person.grades, today) : undefined) ?? person.grade;
382	  }
383	
384	  /** What is due on a claim of the person's, at the grade they have on the claim's date. */
385	  private claimDue(claim: Claim, person: Person): string {
386	    return claimDue(claim, this.rates(), gradeOn(person.grades, claim.date), this.floor.value(), this.late(),
387	      roundsBy(claim, this.claimsOf(person.id)));
388	  }
389	
390	  /** The sum of the dues of the claims the person has that count (n/a ones skipped), 0.00 with none. A
391	   * person shows n/a when neither the grade they have on the sheet's today nor one they had on the date of a
392	   * claim that counts has a rate in force on the sheet's today, unless a settled or stated claim keeps a
393	   * figure. */
394	  protected personDueTotal(person: Person): string {
395	    const counted = this.claimsOf(person.id).filter((c) => this.countsLive(c));
396	    const frozen = counted.some(keepsFigure);
397	    const grades = [this.gradeToday(person), ...counted.map((c) => gradeOn(person.grades, c.date))];
398	    if (!grades.some((g) => g !== undefined && this.rateByGrade().has(g)) && !frozen) return NO_RATE;
399	    return sumAmounts(counted.map((c) => this.claimDue(c, person)).filter((d) => d !== NO_RATE));
400	  }
401	
402	  /** The person's claims that count and are overdue. */
403	  protected overdueOf(person: Person): Claim[] {
404	    const today = this.session.today();
405	    return this.claimsOf(person.id).filter((c) => this.countsLive(c) && isOverdue(c, this.terms.value(), today));
406	  }
407	
408	  /** The sum of the dues of the person's overdue claims that count (n/a ones skipped), 0.00 with none. */
409	  protected overdueTotalOf(person: Person): string {
410	    return sumAmounts(
411	      this.overdueOf(person)
412	        .map((c) => this.claimDue(c, person))
413	        .filter((d) => d !== NO_RATE),
414	    );
415	  }
416	
417	  /** The names of the person's patrons, sorted, comma and space separated. */
418	  protected patronNames(person: Person): string {
419	    return this.patronsOf(person)
420	      .map((p) => p.name)
421	      .sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
422	      .join(', ');
423	  }
424	
425	  /** The person's backing: their patrons' due-totals added up (n/a ones skipped), 0.00 with no patrons. */
426	  protected backing(person: Person): string {
427	    return sumAmounts(this.patronsOf(person).map((p) => this.personDueTotal(p)).filter((d) => d !== NO_RATE));
428	  }
429	
430	  private patronsOf(person: Person): Person[] {
431	    const byId = new Map(this.people().map((p) => [p.id, p]));
432	    return person.patronIds.map((id) => byId.get(id)).filter((p): p is Person => p !== undefined);
433	  }
434	
435	  /** Name another person on the sheet as the person's patron. */
436	  protected addPatron(person: Person, patronId: string): void {
437	    this.patronError.set(null);
438	    this.personError.set(null);
439	    const sheetId = this.session.sheetId();
440	    if (!sheetId) return;
441	    if (!patronId) {
442	      this.patronError.set({ id: person.id, message: 'Choose a patron.' });
443	      return;
444	    }
445	    this.api.addPatron(sheetId, person.id, Number(patronId)).subscribe({
446	      next: (p) => {
447	        if (this.session.sheetId() === sheetId) this.people.update((ps) => ps.map((x) => (x.id === p.id ? p : x)));
448	      },
449	      error: (e: HttpErrorResponse) =>
450	        this.patronError.set({
451	          id: person.id,
452	          message:
453	            e.status === 409
454	              ? 'That person is already a patron.'
455	              : e.status === 422
456	                ? 'A person cannot be their own patron.'
457	                : e.status === 404
458	                  ? 'That person is no longer on this sheet.'
459	                  : 'Could not add that patron.',
460	        }),
461	    });
462	  }
463	
464	  /** Whether a claim counts in the live totals: it counts, and is not an OPEN claim of a held person. */
465	  private countsLive(claim: Claim): boolean {
466	    return counts(claim) && !(claim.status === 'OPEN' && this.heldIds().has(claim.personId));
467	  }
468	
469	  protected rateSaved(rate: Rate): void {
470	    this.rates.update((rs) => [...rs.filter((r) => r.grade !== rate.grade || r.from !== rate.from), rate]);
471	  }
472	
473	  protected periodSaved(period: Period): void {
474	    this.periods.update((ps) =>
475	      [...ps.filter((p) => p.id !== period.id), period].sort((a, b) => (a.from < b.from ? -1 : 1)),
476	    );
477	  }
478	
479	  protected claimSaved(claim: Claim): void {
480	    this.claims.update((cs) =>
481	      cs.some((c) => c.id === claim.id) ? cs.map((c) => (c.id === claim.id ? claim : c)) : [claim, ...cs],
482	    );
483	  }
484	
485	  /** Take a statement for the person, then re-read the sheet's claims, which it binds or unbinds. */
486	  protected statement(person: Person): void {
487	    this.personError.set(null);
488	    this.patronError.set(null);
489	    const sheetId = this.session.sheetId();
490	    if (!sheetId) return;
491	    this.api
492	      .statement(sheetId, person.id)
493	      .pipe(switchMap((p) => forkJoin({ person: of(p), claims: this.claimsApi.list(sheetId) })))
494	      .subscribe({
495	        next: ({ person: p, claims }) => {
496	          if (this.session.sheetId() !== sheetId) return;
497	          this.claims.set(claims);
498	          this.people.update((ps) => ps.map((x) => (x.id === p.id ? p : x)));
499	        },
500	        error: (e: HttpErrorResponse) =>
501	          this.personError.set({
502	            id: person.id,
503	            message: e.status === 404 ? 'That person is no longer on this sheet.' : 'Could not take that statement.',
504	          }),
505	      });
506	  }
507	
508	  protected toggleRetired(event: Event): void {
509	    this.showRetired.set((event.target as HTMLInputElement).checked);
510	  }
511	
512	  /** Retire the person from the date given, the sheet's today when none is. */
513	  protected retire(person: Person, from: string): void {
514	    this.personError.set(null);
515	    this.patronError.set(null);
516	    const sheetId = this.session.sheetId();
517	    if (!sheetId) return;
518	    this.api.retire(sheetId, person.id, from || null).subscribe({
519	      next: (p) => {
520	        if (this.session.sheetId() === sheetId) this.people.update((ps) => ps.map((x) => (x.id === p.id ? p : x)));
521	      },
522	      error: (e: HttpErrorResponse) =>
523	        this.personError.set({
524	          id: person.id,
525	          message: e.status === 404 ? 'That person is no longer on this sheet.' : 'Could not retire that person.',
526	        }),
527	    });
528	  }
529	
530	  /** Put the person on hold, or take them off it when held. */
531	  protected hold(person: Person): void {
532	    this.personError.set(null);
533	    this.patronError.set(null);
534	    const sheetId = this.session.sheetId();
535	    if (!sheetId) return;
536	    this.api.hold(sheetId, person.id).subscribe({
537	      next: (p) => {
538	        if (this.session.sheetId() === sheetId) this.people.update((ps) => ps.map((x) => (x.id === p.id ? p : x)));
539	      },
540	      error: (e: HttpErrorResponse) =>
541	        this.personError.set({
542	          id: person.id,
543	          message: e.status === 404 ? 'That person is no longer on this sheet.' : 'Could not change that hold.',
544	        }),
545	    });
546	  }
547	
548	  /** Add a draft claim for the named person, who is added first when not on the sheet. */
549	  protected quickAdd(): void {
550	    if (this.quickAdding) return;
551	    this.quickError.set(null);
552	    const sheetId = this.session.sheetId();
553	    if (!sheetId) {
554	      this.quickError.set('Load a sheet first.');
555	      return;
556	    }
557	    const value = this.quickForm.getRawValue();
558	    if (!value.name.trim()) {
559	      this.quickError.set('Type a name for the person.');
560	      return;
561	    }
562	    this.quickAdding = true;
563	    this.api.quickAdd(sheetId, value).subscribe({
564	      next: ({ person, personCreated, claim }) => {
565	        this.quickAdding = false;
566	        if (this.session.sheetId() !== sheetId) return;
567	        if (personCreated) this.people.update((ps) => [...ps, person]);
568	        this.claimSaved(claim);
569	        this.quickForm.reset({ name: '', amount: '' }, { emitEvent: false });
570	      },
571	      error: (e: HttpErrorResponse) => {
572	        this.quickAdding = false;
573	        this.quickError.set(this.quickRefusal(e));
574	      },
575	    });
576	  }
577	
578	  private quickRefusal(e: HttpErrorResponse): string {
579	    if (e.status === 400) return 'Type a name and an amount of 0.00 or more, with up to two decimals.';
580	    if (e.status === 423) return 'The sheet\'s today is in a closed period.';
581	    if (e.status === 422) return 'That person is retired from before the sheet\'s today.';
582	    return 'Could not add that claim.';
583	  }
584	
585	  protected edit(person: Person): void {
586	    this.personError.set(null);
587	    this.patronError.set(null);
588	    this.editingId.set(person.id);
589	    this.editingVersion = person.version;
590	    this.form.setValue(
591	      { name: person.name, grade: this.gradeToday(person), gradeFrom: this.session.today() ?? '' },
592	      { emitEvent: false },
593	    );
594	    this.formError.set(null);
595	  }
596	
597	  protected reset(): void {
598	    this.editingId.set(null);
599	    this.editingVersion = null;
600	    this.form.reset({ name: '', grade: 'A', gradeFrom: this.session.today() ?? '' }, { emitEvent: false });
601	    this.formError.set(null);
602	  }
603	
604	  protected submit(): void {
605	    if (this.submitting) return;
606	    this.formError.set(null);
607	    const sheetId = this.session.sheetId();
608	    if (!sheetId) {
609	      this.formError.set('Load a sheet first.');
610	      return;
611	    }
612	    const value = this.form.getRawValue();
613	    if (!value.name.trim()) {
614	      this.formError.set('Type a name for the person.');
615	      return;
616	    }
617	    const id = this.editingId();
618	    this.submitting = true;
619	    const done = () => (this.submitting = false);
620	    if (id === null) {
621	      this.api.add(sheetId, { name: value.name, grade: value.grade }).subscribe({
622	        next: (p) => {
623	          done();
624	          if (this.session.sheetId() === sheetId) this.people.update((ps) => [...ps, p]);
625	          this.reset();
626	        },
627	        error: (e: HttpErrorResponse) => {
628	          done();
629	          this.formError.set(this.refusal(e, 'Could not add that person.'));
630	        },
631	      });
632	    } else {
633	      this.api
634	        .update(sheetId, id, { ...value, gradeFrom: value.gradeFrom || null, version: this.editingVersion ?? undefined })
635	        .subscribe({
636	          next: (p) => {
637	            done();
638	            if (this.session.sheetId() === sheetId) this.people.update((ps) => ps.map((x) => (x.id === p.id ? p : x)));
639	            this.reset();
640	          },
641	          error: (e: HttpErrorResponse) => {
642	            done();
643	            if (e.status === 412) {
644	              this.formError.set('Someone else has saved this person since you opened it. Their values are shown.');
645	              this.showCurrent(sheetId, id);
646	            } else {
647	              this.formError.set(this.refusal(e, 'Could not save that person.'));
648	            }
649	          },
650	        });
651	    }
652	  }
653	
654	  /** Re-read the person from the store and show their current values in the editor, keeping its error. */
655	  private showCurrent(sheetId: string, id: number): void {
656	    this.api.list(sheetId).subscribe((people) => {
657	      if (this.session.sheetId() !== sheetId) return;
658	      this.people.set(people);
659	      const current = people.find((p) => p.id === id);
660	      if (current && this.editingId() === id) {
661	        this.editingVersion = current.version;
662	        this.form.setValue(
663	          { name: current.name, grade: this.gradeToday(current), gradeFrom: this.session.today() ?? '' },
664	          { emitEvent: false },
665	        );
666	      }
667	    });
668	  }
669	
670	  private refusal(e: HttpErrorResponse, fallback: string): string {
671	    return e.status === 409 ? 'That name is already in use on this sheet.' : fallback;
672	  }
673	}
