/** What a claim's late charge goes by: the sheet's today, its terms and its late percent; and the policy date
 * its rounding goes by, the sheet's today when there is none. */
export interface Lateness {
  today: string | null;
  terms: number;
  /** With two decimals, e.g. "10.00". */
  latePct: string;
  policyDate: string | null;
}

/** The date a claim's rounding goes by: a correction's is the date of the claim of its person's (`claims`) it
 * corrects, any other's its own. */
export function roundsBy(claim: Claim, claims: readonly Claim[]): string {
  if (claim.corrects === null) return claim.date;
  return claims.find((c) => c.number === claim.corrects)?.date ?? claim.date;
}

/** Whether a claim's live figures round half up: the date they go by is before the policy date. Otherwise
 * they round half to even. */
function roundsHalfUp(date: string, late: Lateness): boolean {
  return late.policyDate !== null && date < late.policyDate;
}

/** The days in each period an overdue claim gains the late percent for. */
const LATE_PERIOD_DAYS = 30;

/** A settled claim's due is the figure it was settled at (its late charge frozen in); a claim bound by its
 * person's last statement has the figure it was bound to; any other has the figure due at the rate `grade`, the
 * one its person has on the claim's date, has now in force on that date, and at least the sheet's floor (n/a
 * when there is no rate). An overdue claim's due adds its late charge to its figure. Live figures round by the
 * date `roundsBy` (see {@link roundsBy}). */
export function claimDue(
  claim: Claim,
  rates: readonly Rate[],
  grade: Grade | undefined,
  floor: string,
  late: Lateness,
  roundsBy: string = claim.date,
): string {
  if (claim.due !== null) return claim.due;
  const halfUp = roundsHalfUp(roundsBy, late);
  const figure = claim.stated
    ? (claim.statedDue ?? NO_RATE)
    : correctionFloored(claim, dueOf(claim.amount, grade && rateOn(rates, grade, claim.date), halfUp), floor);
  if (figure === NO_RATE) return figure;
  return sumAmounts([figure, lateCharge(claim, figure, late, halfUp)]);
}

/** A due raised to the sheet's floor, except a correction's, which has no floor. */
function correctionFloored(claim: Claim, due: string, floor: string): string {
  return isCorrection(claim) ? due : floored(due, floor);
}

/** The late charge on an overdue claim: the late percent of its figure for every full 30 days it is overdue,
 * rounded like a due; never bound by a statement, it follows the sheet's today. A correction has none. */
function lateCharge(claim: Claim, figure: string, late: Lateness, halfUp: boolean): string {
  if (isCorrection(claim) || !isOverdue(claim, late.terms, late.today) || late.today === null) return '0.00';
  const days = (Date.parse(late.today) - Date.parse(dueBy(claim, late.terms))) / 86_400_000;
  const periods = Math.floor(days / LATE_PERIOD_DAYS);
  return dueOf(figure, timesPct(late.latePct, periods), halfUp);
}

/** A percent with two decimals times a whole number, with two decimals. */
function timesPct(pct: string, times: number): string {
  const [whole, frac = ''] = pct.split('.');
  const hundredths = (BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'))) * BigInt(times);
  return `${hundredths / 100n}.${String(hundredths % 100n).padStart(2, '0')}`;
}

/** Whether a claim keeps a figure whatever the rates: settled at one, or bound to one (not n/a) by a
 * statement. */
export function keepsFigure(claim: Claim): boolean {
  return claim.due !== null || claim.statedDue !== null;
}

/** The date a claim is due by: its date plus the sheet's terms in days (yyyy-mm-dd). */
export function dueBy(claim: Claim, terms: number): string {
  const [y, m, d] = claim.date.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + terms)).toISOString().slice(0, 10);
}

/** Whether a claim is overdue: it is OPEN and its due-by is before the sheet's today. */
export function isOverdue(claim: Claim, terms: number, today: string | null): boolean {
  return claim.status === 'OPEN' && today !== null && dueBy(claim, terms) < today;
}

export interface ClaimForm {
  amount: string;
  /** Null for the sheet's today. */
  date: string | null;
  note: string;
  /** The number of the settled claim a correction corrects; null when none is named. */
  corrects: number | null;
}

/** The sum of claim amounts with two decimals, added up in cents so no rounding creeps in. */
export function sumAmounts(amounts: string[]): string {
  return fromHundredths(amounts.reduce((sum, a) => sum + hundredths(a), 0n));
}

// The claims people make on the active sheet, read and changed through the server.
@Injectable({ providedIn: 'root' })
export class ClaimsApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheetId: string): Observable<Claim[]> {
    return this.http.get<Claim[]>(`${this.url(sheetId)}/claims`, { headers: this.headers() });
  }

  add(sheetId: string, personId: number, form: ClaimForm): Observable<Claim> {
    return this.http.post<Claim>(`${this.url(sheetId)}/people/${personId}/claims`, form, {
      headers: this.headers(),
    });
  }

  update(sheetId: string, id: number, form: ClaimForm): Observable<Claim> {
    return this.http.put<Claim>(`${this.url(sheetId)}/claims/${id}`, form, { headers: this.headers() });
  }

  changeStatus(sheetId: string, id: number, action: ClaimAction): Observable<Claim> {
    return this.http.post<Claim>(`${this.url(sheetId)}/claims/${id}/${action}`, null, { headers: this.headers() });
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}
import { HttpErrorResponse } from '@angular/common/http';
import { Component, computed, effect, inject, input, output, signal, untracked } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';
import { Rate } from '../rates/rates-api';
import { GradeFrom, gradeOn } from '../people/people-api';
import { Period, periodOf } from '../periods/periods-api';
import { SheetFloor } from '../settings/sheet-floor';
import { SheetLatePct } from '../settings/sheet-late-pct';
import { SheetPolicyDate } from '../settings/sheet-policy-date';
import { SheetTerms } from '../settings/sheet-terms';
import { Claim, ClaimAction, ClaimsApi, Lateness, claimDue, dueBy, isOverdue, roundsBy } from './claims-api';

const AMOUNT = /^-?\d{1,10}(\.\d{1,2})?$/;
const NUMBER = /^\d{1,9}$/;

// One person's claims, newest first, and the one form that adds a claim for them or, once a
// claim's editor is opened, saves changes to it.
@Component({
  selector: 'app-claims',
  imports: [ReactiveFormsModule],
  template: `
    <form [formGroup]="form" (ngSubmit)="submit()" data-testid="claim-form">
      <label [for]="'claim-form-amount-' + personId()">Amount</label>
      <input
        [id]="'claim-form-amount-' + personId()"
        data-testid="claim-form-amount"
        inputmode="decimal"
        formControlName="amount"
      />
      <label [for]="'claim-form-date-' + personId()">Date</label>
      <input [id]="'claim-form-date-' + personId()" type="date" data-testid="claim-form-date" formControlName="date" />
      <label [for]="'claim-form-note-' + personId()">Note</label>
      <input [id]="'claim-form-note-' + personId()" data-testid="claim-form-note" formControlName="note" />
      <label [for]="'claim-form-corrects-' + personId()">Corrects claim no.</label>
      <input
        [id]="'claim-form-corrects-' + personId()"
        data-testid="claim-form-corrects"
        inputmode="numeric"
        formControlName="corrects"
      />
      <button type="submit" data-testid="claim-form-submit">
        {{ editingId() === null ? 'Add claim' : 'Save claim' }}
      </button>
      @if (editingId() !== null) {
        <button type="button" data-testid="claim-form-cancel" (click)="reset()">Cancel</button>
      }
    </form>
    @if (formError(); as e) {
      <p role="alert" data-testid="claim-form-error">{{ e }}</p>
    }
    @if (claims().length > 0) {
      <table data-testid="claim-list">
        <caption class="visually-hidden">Claims by {{ personName() }}</caption>
        <thead>
          <tr>
            <th scope="col">No.</th>
            <th scope="col">Amount</th>
            <th scope="col">Date</th>
            <th scope="col">Note</th>
            <th scope="col">Period</th>
            <th scope="col">Due</th>
            <th scope="col">Due by</th>
            <th scope="col">Overdue</th>
            <th scope="col">Stated</th>
            <th scope="col">Status</th>
            <th scope="col">Opened by</th>
            <th scope="col">Corrects</th>
            <th scope="col"><span class="visually-hidden">Actions</span></th>
          </tr>
        </thead>
        <tbody>
          @for (c of claims(); track c.id) {
            <tr [attr.data-testid]="'claim-row-' + c.id">
              <td data-testid="claim-number">{{ c.number ?? '' }}</td>
              <td data-testid="claim-amount">{{ c.amount }}</td>
              <td data-testid="claim-date">{{ c.date }}</td>
              <td data-testid="claim-note">{{ c.note }}</td>
              <td data-testid="claim-period">{{ periodName(c) }}</td>
              <td data-testid="claim-due">{{ due(c) }}</td>
              <td data-testid="claim-due-by">{{ dueBy(c) }}</td>
              <td data-testid="claim-overdue">{{ overdue(c) ? 'yes' : 'no' }}</td>
              <td data-testid="claim-stated">{{ c.stated ? 'yes' : 'no' }}</td>
              <td data-testid="claim-status">{{ c.status }}</td>
              <td data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</td>
              <td data-testid="claim-corrects">{{ c.corrects ?? '' }}</td>
              <td>
                <button
                  type="button"
                  data-testid="claim-edit"
                  [attr.aria-label]="'Edit claim of ' + c.amount + ' on ' + c.date"
                  (click)="edit(c)"
                >
                  Edit
                </button>
                @for (a of actions; track a.action) {
                  <button
                    type="button"
                    [attr.data-testid]="'claim-' + a.action"
                    [attr.aria-label]="a.label + ' claim of ' + c.amount + ' on ' + c.date"
                    (click)="changeStatus(c, a.action)"
                  >
                    {{ a.label }}
                  </button>
                }
                @if (claimError()?.id === c.id) {
                  <p role="alert" data-testid="claim-error">{{ claimError()?.message }}</p>
                }
              </td>
            </tr>
          }
        </tbody>
      </table>
    }
  `,
})
export class Claims {
  private readonly session = inject(Session);
  private readonly api = inject(ClaimsApi);
  private readonly floor = inject(SheetFloor);
  private readonly terms = inject(SheetTerms);
  private readonly latePct = inject(SheetLatePct);
  private readonly policyDate = inject(SheetPolicyDate);
  /** What a late charge goes by: the sheet's today, terms and late percent; and the policy date rounding goes
   * by. */
  private readonly late = computed<Lateness>(() => ({
    today: this.session.today(),
    terms: this.terms.value(),
    latePct: this.latePct.value(),
    policyDate: this.policyDate.value() ?? this.session.today(),
  }));

  readonly personId = input.required<number>();
  readonly personName = input.required<string>();
  /** This person's claims, newest first. */
  readonly claims = input.required<Claim[]>();
  /** This person's dated grades, and the sheet's rates. */
  readonly grades = input.required<readonly GradeFrom[]>();
  readonly rates = input<readonly Rate[]>([]);
  /** The sheet's periods. */
  readonly periods = input<readonly Period[]>([]);
  /** A claim was added or saved. */
  readonly saved = output<Claim>();

  protected readonly actions: { action: ClaimAction; label: string }[] = [
    { action: 'open', label: 'Open' },
    { action: 'settle', label: 'Settle' },
    { action: 'void', label: 'Void' },
  ];
  protected readonly editingId = signal<number | null>(null);
  /** The error of the last action taken on a claim, shown on that claim's row. */
  protected readonly claimError = signal<{ id: number; message: string } | null>(null);
  protected readonly formError = signal<string | null>(null);
  /** Whether a submit is waiting on the server; another submit is ignored until it answers. */
  private submitting = false;
  protected readonly form = new FormGroup({
    amount: new FormControl('', { nonNullable: true }),
    date: new FormControl('', { nonNullable: true }),
    note: new FormControl('', { nonNullable: true }),
    corrects: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    this.form.valueChanges.subscribe(() => this.formError.set(null));
    // A new claim is dated the sheet's today unless another date is picked.
    effect(() => {
      const today = this.session.today() ?? '';
      untracked(() => {
        if (this.editingId() === null && !this.form.controls.date.dirty) {
          this.form.controls.date.setValue(today, { emitEvent: false });
        }
      });
    });
  }

  /** A settled claim shows the due it was settled at; any other is due at the rate the grade its person has on
   * the claim's date has now in force on that date, and at least the sheet's floor, plus its late charge when
   * overdue. */
  protected due(claim: Claim): string {
    return claimDue(claim, this.rates(), gradeOn(this.grades(), claim.date), this.floor.value(), this.late(),
      roundsBy(claim, this.claims()));
  }

  /** The claim's date plus the sheet's terms. */
  protected dueBy(claim: Claim): string {
    return dueBy(claim, this.terms.value());
  }

  /** Whether the claim is OPEN and its due-by is before the sheet's today. */
  protected overdue(claim: Claim): boolean {
    return isOverdue(claim, this.terms.value(), this.session.today());
  }

  /** The name of the period the claim's date falls in; empty when it falls in none. */
  protected periodName(claim: Claim): string {
    return periodOf(this.periods(), claim.date)?.name ?? '';
  }

  protected changeStatus(claim: Claim, action: ClaimAction): void {
    this.claimError.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    this.api.changeStatus(sheetId, claim.id, action).subscribe({
      next: (c) => {
        if (this.session.sheetId() === sheetId) this.saved.emit(c);
      },
      error: (e: HttpErrorResponse) =>
        this.claimError.set({
          id: claim.id,
          message:
            e.status === 403
              ? 'You opened that claim, so someone else must settle it.'
              : e.status === 422
              ? 'That claim\'s due is above the clerk limit, so only a steward can settle it.'
              : e.status === 423
              ? 'That claim is dated in a closed period.'
              : e.status === 409
              ? 'That claim\'s status does not allow that change.'
              : e.status === 404
                ? 'That claim is no longer on this sheet.'
                : 'Could not change that claim\'s status.',
        }),
    });
  }

  protected edit(claim: Claim): void {
    this.claimError.set(null);
    if (claim.status !== 'DRAFT') {
      this.claimError.set({
        id: claim.id,
        message: 'Only a draft claim can be edited. To change it, void it and add a new one.',
      });
      return;
    }
    if (periodOf(this.periods(), claim.date)?.closed) {
      this.claimError.set({ id: claim.id, message: 'That claim is dated in a closed period.' });
      return;
    }
    this.editingId.set(claim.id);
    this.form.setValue(
      { amount: claim.amount, date: claim.date, note: claim.note, corrects: String(claim.corrects ?? '') },
      { emitEvent: false },
    );
    this.formError.set(null);
  }

  protected reset(): void {
    this.editingId.set(null);
    this.form.reset(
      { amount: '', date: this.session.today() ?? '', note: '', corrects: '' },
      { emitEvent: false },
    );
    this.formError.set(null);
  }

  protected submit(): void {
    if (this.submitting) return;
    this.formError.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) {
      this.formError.set('Load a sheet first.');
      return;
    }
    const value = this.form.getRawValue();
    const amount = value.amount.trim();
    if (!AMOUNT.test(amount)) {
      this.formError.set('Type an amount with up to two decimals; a negative one is a correction.');
      return;
    }
    const corrects = value.corrects.trim();
    if (corrects !== '' && !NUMBER.test(corrects)) {
      this.formError.set('Type the number of the settled claim this corrects.');
      return;
    }
    const form = {
      amount,
      date: value.date || null,
      note: value.note.trim(),
      corrects: corrects === '' ? null : Number(corrects),
    };
    const id = this.editingId();
    const request = id === null ? this.api.add(sheetId, this.personId(), form) : this.api.update(sheetId, id, form);
    this.submitting = true;
    request.subscribe({
      next: (c) => {
        this.submitting = false;
        if (this.session.sheetId() === sheetId) this.saved.emit(c);
        this.reset();
      },
      error: (e: HttpErrorResponse) => {
        this.submitting = false;
        this.formError.set(
          e.status === 400
            ? 'A negative amount is a correction: name the number of a settled claim of this person it corrects.'
            : e.status === 404
            ? 'That person or claim is no longer on this sheet.'
            : e.status === 422
              ? 'That claim is dated after its person is retired.'
              : e.status === 423
              ? 'That claim is dated in a closed period.'
              : e.status === 409
                ? 'Only a draft claim can be edited. To change it, void it and add a new one.'
                : 'Could not save that claim.',
        );
      },
    });
  }
}
