import { Grade } from '../people/people-api';

export interface Rate {
  grade: Grade;
  /** The date (yyyy-mm-dd) the rate is in force from; null for from the beginning of time. */
  from: string | null;
  /** A percent with two decimals, e.g. "12.50". */
  rate: string;
}

/**
 * The rate a grade has in force on a date (yyyy-mm-dd): the one with the latest from-date on or
 * before it; none when the date is before every rate of the grade.
 */
export function rateOn(rates: readonly Rate[], grade: Grade, date: string): string | undefined {
  // No from-date sorts as '', before every date.
  let best: Rate | undefined;
  for (const r of rates) {
    const from = r.from ?? '';
    if (r.grade === grade && from <= date && (!best || from > (best.from ?? ''))) best = r;
  }
  return best?.rate;
}

/** Shown in place of a due whose grade has no rate. */
export const NO_RATE = 'n/a';

/** Hundredths of a decimal with up to two decimals, e.g. "12.5" is 1250 and "-0.3" is -30. */
export function hundredths(value: string): bigint {
  const negative = value.startsWith('-');
  const [whole, frac = ''] = (negative ? value.slice(1) : value).split('.');
  const abs = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'));
  return negative ? -abs : abs;
}

/** Hundredths as a decimal with two decimals, e.g. -30 is "-0.30". */
export function fromHundredths(value: bigint): string {
  const abs = value < 0n ? -value : value;
  return `${value < 0n ? '-' : ''}${abs / 100n}.${String(abs % 100n).padStart(2, '0')}`;
}

/**
 * What is due on an amount at a rate: the amount times the rate, divided by 100, rounded to two
 * decimals, a half to the even cent, or up when `halfUp`. Worked in whole numbers so no rounding
 * creeps in; n/a when there is no rate.
 */
export function dueOf(amount: string, rate: string | undefined, halfUp = false): string {
  if (rate === undefined) return NO_RATE;
  // cents × hundredths of a percent is in ten-thousandths of a cent; round to cents, a half to the even
  // cent (or up), worked on the size so a correction's negative amount rounds the same way.
  const exact = hundredths(amount) * hundredths(rate);
  const size = exact < 0n ? -exact : exact;
  const rest = size % 10000n;
  let cents = size / 10000n;
  if (rest > 5000n || (rest === 5000n && (halfUp || cents % 2n === 1n))) cents += 1n;
  return fromHundredths(exact < 0n ? -cents : cents);
}

/** A due raised to the floor when it is below it; n/a stays n/a. */
export function floored(due: string, floor: string): string {
  if (due === NO_RATE) return due;
  return hundredths(due) < hundredths(floor) ? floor : due;
}

// The rate for each grade on the active sheet, read and changed through the server.
@Injectable({ providedIn: 'root' })
export class RatesApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheetId: string): Observable<Rate[]> {
    return this.http.get<Rate[]>(this.url(sheetId), { headers: this.headers() });
  }

  set(sheetId: string, grade: Grade, rate: string, from: string | null): Observable<Rate> {
    return this.http.put<Rate>(`${this.url(sheetId)}/${grade}`, { rate, from }, { headers: this.headers() });
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/rates`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Session } from '../../core/session';
import { Claim } from '../claims/claims-api';

export type Grade = 'A' | 'B' | 'C';

/** A grade a person has from a date (yyyy-mm-dd); null for from the beginning of time. */
export interface GradeFrom {
  grade: Grade;
  from: string | null;
}

/** The grade in force on a date (yyyy-mm-dd): the one with the latest from-date on or before it. */
export function gradeOn(grades: readonly GradeFrom[], date: string): Grade | undefined {
  // No from-date sorts as '', before every date.
  let best: GradeFrom | undefined;
  for (const g of grades) {
    const from = g.from ?? '';
    if (from <= date && (!best || from > (best.from ?? ''))) best = g;
  }
  return best?.grade;
}

export interface Person {
  id: number;
  name: string;
  /** The grade in force on the sheet's today when the person was read. */
  grade: Grade;
  /** Every grade recorded for the person, by from-date, the first one given (from the beginning of time) first. */
  grades: GradeFrom[];
  /** Raised each time the person is saved. */
  version: number;
  /** How many statements were taken for the person. */
  statementCount: number;
  /** The last statement's due-total ("n/a" when it was), and the sheet's today when it was taken; null before
   * the first. */
  statedTotal: string | null;
  statementDate: string | null;
  /** The date the person is retired from; null while not retired. */
  retiredFrom: string | null;
  /** Whether the person is on hold: while held, their OPEN claims count in no live total. */
  held: boolean;
  /** The ids of the people named as the person's patrons, in the order they were named. */
  patronIds: number[];
}

export interface PersonForm {
  name: string;
  grade: Grade;
  /** The date a saved grade is in force from (yyyy-mm-dd); null for the sheet's today. A new person's first
   * grade applies from the beginning of time. */
  gradeFrom?: string | null;
  /** The version of the person the editor loaded; a save is refused once someone else has saved since. */
  version?: number;
}

export interface QuickAddForm {
  name: string;
  amount: string;
}

/** What a quick-add stored: the claim, and its person, who is new when `personCreated`. */
export interface QuickAdded {
  person: Person;
  personCreated: boolean;
  claim: Claim;
}

// The people kept on the active sheet, read and changed through the server.
@Injectable({ providedIn: 'root' })
export class PeopleApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheetId: string): Observable<Person[]> {
    return this.http.get<Person[]>(this.url(sheetId), { headers: this.headers() });
  }

  add(sheetId: string, form: PersonForm): Observable<Person> {
    return this.http.post<Person>(this.url(sheetId), form, { headers: this.headers() });
  }

  update(sheetId: string, id: number, form: PersonForm): Observable<Person> {
    return this.http.put<Person>(`${this.url(sheetId)}/${id}`, form, { headers: this.headers() });
  }

  /** Take a statement for the person. */
  statement(sheetId: string, id: number): Observable<Person> {
    return this.http.post<Person>(`${this.url(sheetId)}/${id}/statement`, null, { headers: this.headers() });
  }

  /** Retire the person from a date, the sheet's today when none is given. */
  retire(sheetId: string, id: number, from: string | null): Observable<Person> {
    return this.http.post<Person>(`${this.url(sheetId)}/${id}/retire`, { from }, { headers: this.headers() });
  }

  /** Put the person on hold, or take them off it when held. */
  hold(sheetId: string, id: number): Observable<Person> {
    return this.http.post<Person>(`${this.url(sheetId)}/${id}/hold`, null, { headers: this.headers() });
  }

  /** Name another person on the sheet as the person's patron. */
  addPatron(sheetId: string, id: number, patronId: number): Observable<Person> {
    return this.http.post<Person>(`${this.url(sheetId)}/${id}/patrons`, { patronId }, { headers: this.headers() });
  }

  /** Add a draft claim for the named person, adding them with grade A first when not on the sheet. */
  quickAdd(sheetId: string, form: QuickAddForm): Observable<QuickAdded> {
    return this.http.post<QuickAdded>(`/api/sheets/${encodeURIComponent(sheetId)}/quick-add`, form, {
      headers: this.headers(),
    });
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/people`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Session } from '../../core/session';

export interface Period {
  id: number;
  /** Unique on the sheet. */
  name: string;
  /** yyyy-mm-dd, both inclusive. */
  from: string;
  to: string;
  closed: boolean;
  /** The due-total fixed when it closed; null while open. */
  closedTotal: string | null;
}

export interface PeriodForm {
  name: string;
  from: string;
  to: string;
}

/** The period whose dates contain a date (yyyy-mm-dd); none when no period does. */
export function periodOf(periods: readonly Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}

// The periods of the active sheet, read, added, closed and reopened through the server.
@Injectable({ providedIn: 'root' })
export class PeriodsApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheetId: string): Observable<Period[]> {
    return this.http.get<Period[]>(this.url(sheetId), { headers: this.headers() });
  }

  add(sheetId: string, form: PeriodForm): Observable<Period> {
    return this.http.post<Period>(this.url(sheetId), form, { headers: this.headers() });
  }

  close(sheetId: string, id: number): Observable<Period> {
    return this.http.post<Period>(`${this.url(sheetId)}/${id}/close`, null, { headers: this.headers() });
  }

  reopen(sheetId: string, id: number): Observable<Period> {
    return this.http.post<Period>(`${this.url(sheetId)}/${id}/reopen`, null, { headers: this.headers() });
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/periods`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}

